insert into kafaa_roleplay_scenarios (id, code, kind, title_en, title_ar, summary_en, summary_ar, setting_en, setting_ar, counterpart_en, counterpart_ar, role_en, role_ar, core_skill_ids, skill_ids, level, pass_pct, est_minutes, turns, rubric, sources, status, listed, version, sort, updated_by, updated_at) values
('rp-kt-02', 'RP-KT-02', 'knowledge_transfer', 'Passing on your know-how before a rotation', 'نقل خبرتك قبل الانتقال إلى مهمة أخرى', 'Draft: you are leaving for a rotation; run a session that hands your know-how to the colleague who replaces you.', 'مسودة: ستنتقل إلى مهمة أخرى؛ أدر جلسة تنقل فيها خبرتك إلى الزميل الذي سيحل محلك.', 'You start a six-month rotation next month. Your replacement joins you for a handover session on the inspection routines you run.', 'تبدأ الشهر القادم مهمة لمدة ستة أشهر. ينضم إليك من سيحل محلك في جلسة تسليم لروتينات الفحص التي تديرها.', 'Your replacement (role card)', 'الزميل البديل (بطاقة دور)', 'Session lead', 'قائد الجلسة', array['cs-cross-cultural','cs-developing']::text[], array['sk-fs-tr-crosscultural','sk-fs-tr-empathy']::text[], 1, 60, 20, '[{"id":"open","prompt_en":"Shall I just start explaining how we inspect the pump seals?","prompt_ar":"هل أبدأ مباشرة في شرح طريقة فحصنا لموانع التسرب؟","hint_en":"Set the goal and say what you need.","hint_ar":"حدد الهدف وقل ما تحتاجه.","example_en":"Thank you for coming. Before you start, our goal today is to understand your seal inspection method well enough to train our own team. We need most detail on the acceptance limits and the common mistakes.","example_ar":"شكراً لحضورك. قبل أن تبدأ، الهدف اليوم أن نفهم طريقتك في فحص موانع التسرب بما يكفي لتدريب فريقنا. نحتاج إلى أكبر قدر من التفاصيل عن حدود القبول والأخطاء الشائعة.","criteria":["goal","needs"]},{"id":"check","prompt_en":"So the wear groove is measured at four points, and anything over the limit is rejected. Clear so far?","prompt_ar":"إذن يُقاس أخدود التآكل عند أربع نقاط، ويُرفض كل ما يتجاوز الحد. هل الأمر واضح حتى الآن؟","hint_en":"Paraphrase and check with a question.","hint_ar":"أعد الصياغة وتحقق بسؤال.","example_en":"Yes. If I understand correctly, you measure at four points around the face and reject the seal if any single point is over the limit, not the average. Is that right?","example_ar":"نعم. إذا فهمت جيداً، تقيسون عند أربع نقاط حول الوجه وترفضون مانع التسرب إذا تجاوزت أي نقطة واحدة الحد، وليس المتوسط. هل هذا صحيح؟","criteria":["paraphrase","check_understanding"]},{"id":"context","prompt_en":"That is how we do it at our plant.","prompt_ar":"هكذا نفعل ذلك في محطتنا.","hint_en":"Relate it to your own procedure and capture it.","hint_ar":"اربطه بإجراءاتك ووثّقه.","example_en":"That is useful. Our procedure here uses a different gauge, so I will note where the steps differ and we will record your method as a knowledge asset for review.","example_ar":"هذا مفيد. يستخدم الإجراء لدينا مقياساً مختلفاً، لذلك سأدوّن مواضع الاختلاف. سنوثق طريقتك أصلاً معرفياً للمراجعة.","criteria":["context","capture"]},{"id":"close","prompt_en":"Anything else?","prompt_ar":"هل هناك شيء آخر؟","hint_en":"Summarise and agree the follow-up.","hint_ar":"لخّص واتفق على المتابعة.","example_en":"Let me summarise the key points: four measuring points, reject on any single point, and record the gauge used. I will send the notes to you for checking before our next session.","example_ar":"دعني أذكر النقاط الرئيسية: أربع نقاط قياس، والرفض عند أي نقطة واحدة، وتسجيل المقياس المستخدم. سأرسل الملاحظات إليك للتحقق قبل الجلسة القادمة.","criteria":["summary","next"]}]'::jsonb, '[{"id":"goal","label_en":"Sets the goal","label_ar":"يحدد الهدف","desc_en":"States the goal or agenda of the session.","desc_ar":"يذكر هدف الجلسة أو جدولها.","tip_en":"Open with what you want to be able to do afterwards.","tip_ar":"ابدأ بما تريد أن تستطيع فعله بعد الجلسة.","check":{"type":"cues","cues":["goal","objective","agenda","today we","purpose","aim","الهدف","جدول","هدفنا","الغرض"]}},{"id":"needs","label_en":"Says what you need most","label_ar":"يذكر ما تحتاجه أكثر","desc_en":"Says what the team needs most from the expert.","desc_ar":"يذكر ما يحتاجه الفريق أكثر من الخبير.","tip_en":"Point the expert at the part that matters to you.","tip_ar":"وجّه الخبير إلى الجزء الذي يهمك.","check":{"type":"cues","cues":["we need","we want","i would like","focus on","most useful","نحتاج","نريد","أود","نركز"]}},{"id":"paraphrase","label_en":"Checks by paraphrasing","label_ar":"يتحقق بإعادة الصياغة","desc_en":"Restates the point in their own words (if I understand, in other words).","desc_ar":"يعيد صياغة الفكرة بكلماته (إذا فهمت، بمعنى).","tip_en":"Say it back in your words.","tip_ar":"أعد قولها بكلماتك.","check":{"type":"cues","cues":["so you mean","if i understand","in other words","to check","so what you are saying","let me repeat","إذا فهمت","بمعنى","أي أن","دعني أعيد"]}},{"id":"check_understanding","label_en":"Checks understanding with a question","label_ar":"يتحقق من الفهم بسؤال","desc_en":"Ends with a real question (a ? or ؟) that invites the other person to respond.","desc_ar":"ينتهي بسؤال حقيقي (؟ أو ?) يدعو الطرف الآخر إلى الرد.","tip_en":"Ask one open question before you move on.","tip_ar":"اطرح سؤالاً مفتوحاً واحداً قبل أن تنتقل.","check":{"type":"question"}},{"id":"context","label_en":"Relates it to your context","label_ar":"يربطها بسياقك","desc_en":"Notes how your own plant or procedure differs.","desc_ar":"يلاحظ كيف تختلف محطتك أو إجراءاتك.","tip_en":"Ask yourself what is different here.","tip_ar":"اسأل نفسك ما المختلف هنا.","check":{"type":"cues","cues":["our plant","here","our procedure","differ*","locally","في محطتنا","لدينا","هنا","يختلف","تختلف"]}},{"id":"capture","label_en":"Captures the knowledge","label_ar":"يوثق المعرفة","desc_en":"Says how the knowledge will be written down or recorded.","desc_ar":"يذكر كيف ستُدوّن المعرفة أو تُسجل.","tip_en":"Agree how it will be captured before the expert leaves.","tip_ar":"اتفق على طريقة التوثيق قبل مغادرة الخبير.","check":{"type":"cues","cues":["write","record*","capture","document*","knowledge asset","note*","نوثق","أسجل","توثيق","سنوثق","نسجل"]}},{"id":"summary","label_en":"Summarises the key points","label_ar":"يلخص النقاط الرئيسية","desc_en":"Summarises the key points at the end.","desc_ar":"يلخص النقاط الرئيسية في النهاية.","tip_en":"Close with three key points.","tip_ar":"اختم بثلاث نقاط رئيسية.","check":{"type":"cues","cues":["summary","to summarise","key points","three points","in short","الخلاصة","النقاط الرئيسية","باختصار"]}},{"id":"next","label_en":"Agrees the follow-up","label_ar":"يتفق على المتابعة","desc_en":"Agrees what happens next (send notes, a next session).","desc_ar":"يتفق على ما يحدث بعد ذلك (إرسال الملاحظات أو جلسة قادمة).","tip_en":"End with who sends what, and when.","tip_ar":"اختم بمن يرسل ماذا ومتى.","check":{"type":"cues","cues":["next session","follow-up","follow up","send","share","الجلسة القادمة","متابعة","سأرسل","نشارك"]}}]'::jsonb, '[{"label":"LinkedIn Learning · Role play with AI coach","url":"https://training.talent.linkedin.com/introducing-role-play-with-ai-coach","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"Udemy · AI-powered role play for business and communication skills (custom scenarios)","url":"https://about.udemy.com/press-releases/udemy-launches-ai-powered-role-play-to-coach-professionals-on-business-and-communication-skills/","as_of":"2026-10-10","benchmark_id":"SKILLS-TECH"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10","benchmark_id":"IAEA-1917"}]'::jsonb, 'draft', false, 1, 7, 'p-training-mgr', '2026-09-29T09:00:00Z')
